mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CoinTracker Pro — Cryptocurrency Prices, Charts and Market Capitalizations</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: oklch(0.985 0.004 260);
      --panel: oklch(1 0 0);
      --panel-soft: oklch(0.975 0.006 260);
      --text: oklch(0.23 0.02 260);
      --muted: oklch(0.51 0.02 260);
      --border: oklch(0.9 0.012 260);
      --brand: oklch(0.55 0.18 255);
      --brand-soft: oklch(0.95 0.03 255);
      --green: #16c784;
      --red: #ea3943;
      --radius: 12px;
      --mono: "IBM Plex Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
      --sans: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
      --shadow: 0 1px 2px oklch(0.25 0.02 260 / 0.05), 0 8px 24px oklch(0.25 0.02 260 / 0.06);
    }

    * { box-sizing: border-box; }
    body {
      margin: 0;
      font-family: var(--sans);
      background: var(--bg);
      color: var(--text);
      -webkit-font-smoothing: antialiased;
      text-rendering: optimizeLegibility;
    }

    .shell {
      width: min(1600px, calc(100% - 24px));
      margin: 14px auto 28px;
    }

    .panel {
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: var(--radius);
      box-shadow: var(--shadow);
    }

    .topbar {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      padding: 10px 14px;
      font-size: 12px;
      color: var(--muted);
      overflow: auto;
      white-space: nowrap;
    }

    .metrics {
      display: flex;
      gap: 18px;
      align-items: center;
    }

    .metric strong {
      color: var(--text);
      margin-left: 6px;
      font-family: var(--mono);
      font-variant-numeric: tabular-nums;
      letter-spacing: -0.01em;
      font-size: 12px;
    }

    .pos { color: var(--green) !important; }
    .neg { color: var(--red) !important; }

    .nav {
      margin-top: 12px;
      padding: 12px 14px;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      flex-wrap: wrap;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      letter-spacing: -0.02em;
      font-size: 19px;
      color: var(--text);
    }

    .brand-badge {
      width: 28px;
      height: 28px;
      border-radius: 8px;
      background: linear-gradient(135deg, oklch(0.62 0.19 255), oklch(0.52 0.2 285));
      display: grid;
      place-items: center;
      color: #fff;
      font-size: 14px;
    }

    .navlinks { display: flex; gap: 6px; flex-wrap: wrap; }

    .navlinks a {
      text-decoration: none;
      color: var(--muted);
      font-size: 13px;
      padding: 8px 10px;
      border-radius: 8px;
      transition: 160ms ease;
      font-weight: 500;
    }

    .navlinks a:hover, .navlinks a.active {
      background: var(--brand-soft);
      color: var(--brand);
    }

    .banner {
      margin-top: 12px;
      padding: 14px;
      position: relative;
      overflow: hidden;
    }

    .slides { display: flex; transition: transform 320ms ease; }

    .slide {
      min-width: 100%;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 14px;
      padding: 14px;
      border-radius: 10px;
      background: linear-gradient(90deg, oklch(0.96 0.028 255), oklch(0.97 0.022 210));
      border: 1px solid oklch(0.87 0.03 250);
    }

    .slide h3 { margin: 0 0 6px; font-size: 16px; }
    .slide p { margin: 0; font-size: 13px; color: var(--muted); }
    .slide button {
      border: 0;
      background: var(--brand);
      color: #fff;
      border-radius: 8px;
      padding: 10px 14px;
      font-weight: 600;
      cursor: pointer;
    }

    .banner-controls {
      position: absolute;
      right: 22px;
      top: 50%;
      transform: translateY(-50%);
      display: flex;
      gap: 6px;
    }

    .icon-btn {
      width: 30px;
      height: 30px;
      border-radius: 8px;
      border: 1px solid var(--border);
      background: #fff;
      color: var(--muted);
      cursor: pointer;
      font-weight: 700;
    }

    .ai-alerts {
      margin-top: 12px;
      padding: 10px 14px;
      display: flex;
      gap: 10px;
      align-items: center;
      font-size: 13px;
    }

    .pulse {
      width: 8px;
      height: 8px;
      border-radius: 50%;
      background: var(--brand);
      animation: pulse 1.5s infinite;
    }

    @keyframes pulse {
      0%, 100% { box-shadow: 0 0 0 0 oklch(0.55 0.18 255 / 0.5); }
      70% { box-shadow: 0 0 0 10px oklch(0.55 0.18 255 / 0); }
    }

    .tabbar {
      margin-top: 12px;
      padding: 10px;
      display: flex;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: 10px;
    }

    .tabs { display: flex; gap: 6px; flex-wrap: wrap; }

    .tab {
      border: 1px solid var(--border);
      background: #fff;
      color: var(--muted);
      padding: 8px 12px;
      border-radius: 999px;
      font-size: 12px;
      cursor: pointer;
      transition: 160ms ease;
    }

    .tab.active {
      background: var(--brand-soft);
      color: var(--brand);
      border-color: oklch(0.85 0.06 255);
      font-weight: 600;
    }

    .table-wrap {
      margin-top: 12px;
      padding: 10px;
      overflow: hidden;
    }

    .controls {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 10px;
      padding: 4px 2px 10px;
    }

    .btn {
      border: 1px solid var(--border);
      background: #fff;
      padding: 8px 10px;
      border-radius: 8px;
      font-size: 12px;
      color: var(--text);
      cursor: pointer;
      transition: 160ms ease;
    }

    .btn:hover { border-color: oklch(0.82 0.03 260); background: var(--panel-soft); }

    .drawer {
      display: none;
      border: 1px solid var(--border);
      border-radius: 10px;
      padding: 10px;
      margin-bottom: 10px;
      background: var(--panel-soft);
      font-size: 12px;
      color: var(--muted);
      grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
      gap: 10px;
    }

    .drawer.active { display: grid; }

    .table-scroll { overflow: auto; border: 1px solid var(--border); border-radius: 10px; }

    table {
      width: 100%;
      min-width: 1320px;
      border-collapse: collapse;
      font-size: 12px;
      background: #fff;
    }

    thead th {
      text-align: right;
      color: var(--muted);
      font-weight: 600;
      padding: 10px 8px;
      border-bottom: 1px solid var(--border);
      background: var(--panel-soft);
      position: sticky;
      top: 0;
      z-index: 5;
      cursor: pointer;
      user-select: none;
    }

    thead th:first-child, tbody td:first-child,
    thead th:nth-child(2), tbody td:nth-child(2) { text-align: left; }

    tbody td {
      padding: 10px 8px;
      border-bottom: 1px solid var(--border);
      text-align: right;
      font-family: var(--mono);
      font-variant-numeric: tabular-nums;
      color: oklch(0.33 0.02 260);
    }

    tbody tr:hover { background: oklch(0.97 0.01 250); }

    .coin {
      display: flex;
      align-items: center;
      gap: 8px;
      font-family: var(--sans);
      color: var(--text);
      font-weight: 600;
    }

    .sym {
      color: var(--muted);
      font-weight: 500;
      font-size: 11px;
    }

    .dot {
      width: 20px;
      height: 20px;
      border-radius: 50%;
      display: inline-grid;
      place-items: center;
      color: #fff;
      font-size: 10px;
      font-weight: 700;
      background: linear-gradient(140deg, oklch(0.63 0.16 250), oklch(0.5 0.2 285));
      flex: 0 0 auto;
    }

    .spark {
      width: 130px;
      height: 34px;
    }

    .pagination {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 8px;
      padding: 10px 0 2px;
      flex-wrap: wrap;
      font-size: 12px;
      color: var(--muted);
    }

    .pages { display: flex; gap: 4px; align-items: center; }

    .page-btn {
      min-width: 30px;
      height: 30px;
      padding: 0 8px;
      border: 1px solid var(--border);
      border-radius: 8px;
      background: #fff;
      cursor: pointer;
      font-size: 12px;
      color: var(--text);
    }

    .page-btn.active { background: var(--brand); color: #fff; border-color: var(--brand); }

    .summary, .info, footer {
      margin-top: 12px;
      padding: 14px;
    }

    .summary h2, .info h2 { margin: 0 0 8px; font-size: 18px; }
    .summary p, .info p { margin: 0; font-size: 13px; line-height: 1.6; color: var(--muted); }

    .readmore {
      margin-top: 10px;
      border: 0;
      background: none;
      color: var(--brand);
      cursor: pointer;
      font-size: 13px;
      padding: 0;
      font-weight: 600;
    }

    .hidden { display: none; }

    .footer-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 14px;
    }

    .footer-grid h4 { margin: 0 0 8px; font-size: 12px; color: var(--text); }
    .footer-grid p { margin: 0; font-size: 12px; color: var(--muted); line-height: 1.8; }
    .copyright { margin-top: 12px; font-size: 12px; color: var(--muted); }

    @media (max-width: 860px) {
      .shell { width: calc(100% - 12px); }
      .topbar { font-size: 11px; }
      .slide { flex-direction: column; align-items: flex-start; }
      .banner-controls { position: static; transform: none; margin-top: 10px; }
    }
  </style>
</head>
<body>
  <div class="shell">
    <header class="panel topbar" aria-label="Market Overview Stats">
      <div class="metrics">
        <span class="metric">Global Market Cap:<strong>$2.56T</strong><strong class="pos">1.46%</strong></span>
        <span class="metric">CMC20:<strong>$154.29</strong><strong class="pos">0.21%</strong></span>
        <span class="metric">Fear &amp; Greed:<strong>57</strong><strong>Neutral</strong></span>
        <span class="metric">Altcoin Season:<strong>37/100</strong></span>
      </div>
      <strong style="font-size:12px;color:var(--text)">Live Market Snapshot</strong>
    </header>

    <nav class="panel nav" aria-label="Primary Navigation">
      <div class="brand"><span class="brand-badge">₿</span>CoinTracker Pro</div>
      <div class="navlinks">
        <a href="index.html" class="active">Cryptocurrencies</a>
        <a href="index.html">Dashboards</a>
        <a href="index.html">Exchanges</a>
        <a href="index.html">DexScan</a>
      </div>
    </nav>

    <section class="panel banner" aria-label="Promotional Banner">
      <div class="slides" id="slides"></div>
      <div class="banner-controls">
        <button class="icon-btn" id="prevSlide" aria-label="Previous banner">‹</button>
        <button class="icon-btn" id="nextSlide" aria-label="Next banner">›</button>
      </div>
    </section>

    <section class="panel ai-alerts" aria-label="AI Alerts Bar">
      <span class="pulse" aria-hidden="true"></span>
      <strong>AI Alerts:</strong>
      <span>BTC options skew rising; ETH/BTC pair showing accumulation zones; high inflow on SOL ecosystem tokens.</span>
    </section>

    <section class="panel tabbar" aria-label="Filters">
      <div class="tabs" id="categoryTabs"></div>
      <div class="tabs" id="networkTabs"></div>
    </section>

    <main class="panel table-wrap">
      <div class="controls">
        <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
          <button class="btn" id="columnsBtn" aria-expanded="false">Columns</button>
          <button class="btn" id="filtersBtn" aria-expanded="false">Filters</button>
        </div>
        <div style="font-size:12px;color:var(--muted)" id="tableMeta">Showing top assets by market cap</div>
      </div>

      <div class="drawer" id="columnsPanel" aria-label="Column Visibility Panel"></div>
      <div class="drawer" id="filtersPanel" aria-label="Filter Panel"></div>

      <div class="table-scroll">
        <table aria-label="Cryptocurrency rankings table">
          <thead>
            <tr id="tableHead"></tr>
          </thead>
          <tbody id="tableBody"></tbody>
        </table>
      </div>

      <div class="pagination" aria-label="Table Pagination">
        <span id="pageInfo">Page 1 of 84</span>
        <div class="pages" id="pages"></div>
      </div>
    </main>

    <section class="panel summary" aria-label="Market Summary">
      <h2>Market Summary</h2>
      <p>
        The global cryptocurrency market cap today is <strong>$2.56T</strong>, a <strong class="pos">1.47%</strong> change in the last 24 hours.
        Total crypto market volume over the last 24 hours is <strong>$156.9B</strong>. DeFi volume currently represents <strong>14.51%</strong> of total market 24h volume,
        while stablecoins account for the majority of volume. Bitcoin dominance stands at <strong>59.04%</strong>.
      </p>
      <p id="moreSummary" class="hidden" style="margin-top:8px;">
        Market breadth has improved as large-cap assets regain momentum, but sector rotation remains active across Layer-1, AI, and DeFi categories.
        Traders continue to track macro catalysts, ETF flows, and on-chain liquidity trends for directional confirmation.
      </p>
      <button class="readmore" id="readMore">Read More</button>
    </section>

    <section class="panel info" aria-label="Information Content">
      <h2>Today’s Cryptocurrency Prices by Market Cap</h2>
      <p>
        The global crypto market cap is <strong>$2.56T</strong>. Get real-time prices, market caps, 24-hour trading volume, circulating supply,
        and historic performance metrics for the leading digital assets. Prices are aggregated from active exchange pairs and normalized in USD.
        Valuations are estimated as circulating supply multiplied by reference price.
      </p>
    </section>

    <footer class="panel" aria-label="Footer">
      <div class="footer-grid">
        <div><h4>Products</h4><p>Cryptocurrencies · Exchanges · DexScan · Portfolio · Watchlist</p></div>
        <div><h4>Company</h4><p>About · Terms of Use · Privacy Policy · Methodology · Disclaimer</p></div>
        <div><h4>Support</h4><p>FAQ · Glossary · Crypto Learning Center · API Documentation</p></div>
        <div><h4>Community</h4><p>Twitter · Telegram · Discord · Instagram</p></div>
      </div>
      <div class="copyright">© 2025 CoinTracker Pro. All rights reserved.</div>
    </footer>
  </div>

  <script>
    const categories = ["Top", "Trending", "Watchlist", "Prediction Markets", "Most Visited", "New"];
    const networks = ["All Networks", "BSC", "Solana", "Base", "Ethereum", "More"];
    const columnsDef = [
      { key: "rank", label: "#", sortable: true },
      { key: "name", label: "Name", sortable: true },
      { key: "price", label: "Price", sortable: true },
      { key: "h1", label: "1h %", sortable: true },
      { key: "h24", label: "24h %", sortable: true },
      { key: "d7", label: "7d %", sortable: true },
      { key: "marketCap", label: "Market Cap", sortable: true },
      { key: "volume", label: "Volume(24h)", sortable: true },
      { key: "supply", label: "Circulating Supply", sortable: true },
      { key: "spark", label: "Last 7 Days", sortable: false }
    ];

    const promotionalSlides = [
      { title: "Institutional Flows Dashboard", text: "Track ETF and whale wallet flows with premium analytics.", cta: "Explore Pro" },
      { title: "Set Smart Price Alerts", text: "Get AI-powered volatility alerts for your watchlist instantly.", cta: "Create Alerts" },
      { title: "New: On-chain Risk Monitor", text: "Identify abnormal token movement before market reacts.", cta: "Open Monitor" }
    ];

    const baseCoins = [
      ["Bitcoin", "BTC", 75612.78, "#f7931a"],
      ["Ethereum", "ETH", 2356.00, "#627eea"],
      ["Tether", "USDT", 1.00, "#26a17b"],
      ["BNB", "BNB", 610.42, "#f3ba2f"],
      ["Solana", "SOL", 168.35, "#14f195"],
      ["XRP", "XRP", 0.62, "#23292f"],
      ["USDC", "USDC", 1.00, "#2775ca"],
      ["Dogecoin", "DOGE", 0.19, "#c2a633"],
      ["Cardano", "ADA", 0.71, "#0033ad"],
      ["TRON", "TRX", 0.13, "#ef0027"]
    ];

    function formatMoney(value) {
      if (value >= 1e12) return `$${(value / 1e12).toFixed(2)}T`;
      if (value >= 1e9) return `$${(value / 1e9).toFixed(2)}B`;
      if (value >= 1e6) return `$${(value / 1e6).toFixed(2)}M`;
      return `$${value.toLocaleString(undefined, { maximumFractionDigits: 2 })}`;
    }

    function formatPrice(value) {
      const digits = value >= 1000 ? 2 : value >= 1 ? 2 : 4;
      return `$${value.toLocaleString(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
    }

    function pct(v) {
      const sign = v > 0 ? "+" : "";
      return `${sign}${v.toFixed(2)}%`;
    }

    function seeded(i, scale = 1) {
      const x = Math.sin(i * 999) * 10000;
      return ((x - Math.floor(x)) - 0.5) * scale;
    }

    function buildDataset(page = 1) {
      const list = [];
      for (let i = 0; i < 100; i++) {
        const rank = (page - 1) * 100 + i + 1;
        const tpl = baseCoins[i % baseCoins.length];
        const drift = 1 + seeded(rank, 0.5) / 3;
        const price = tpl[2] * Math.max(0.25, drift);
        const marketCap = Math.abs(price * (3e7 + rank * 140000));
        const volume = marketCap * (0.03 + Math.abs(seeded(rank + 20, 0.2)));
        const supply = Math.max(100000, marketCap / Math.max(price, 0.01));
        const h1 = seeded(rank + 2, 2.8);
        const h24 = seeded(rank + 9, 8.2);
        const d7 = seeded(rank + 33, 20);

        let category = categories[0];
        if (rank % 5 === 0) category = "Trending";
        if (rank % 7 === 0) category = "Watchlist";
        if (rank % 11 === 0) category = "Prediction Markets";
        if (rank % 13 === 0) category = "Most Visited";
        if (rank % 17 === 0) category = "New";

        const network = rank % 6 === 0 ? "BSC" : rank % 5 === 0 ? "Solana" : rank % 4 === 0 ? "Base" : rank % 3 === 0 ? "Ethereum" : "All Networks";

        list.push({
          rank,
          name: `${tpl[0]} ${rank > 10 ? rank : ""}`.trim(),
          symbol: tpl[1],
          color: tpl[3],
          price,
          h1,
          h24,
          d7,
          marketCap,
          volume,
          supply,
          category,
          network
        });
      }

      list[0].price = 75612.78;
      list[1].price = 2356.00;
      list[0].marketCap = 1.51e12;
      list[1].volume = 2.8435e11;
      list[0].supply = 20010000;
      list[9].price = 88.25;
      return list;
    }

    let state = {
      category: "Top",
      network: "All Networks",
      page: 1,
      sortKey: "rank",
      sortDir: "asc",
      slide: 0,
      columns: Object.fromEntries(columnsDef.map(c => [c.key, true])),
      filters: { positive24h: false, largeCapOnly: false, highVolume: false }
    };

    const categoryTabs = document.getElementById("categoryTabs");
    const networkTabs = document.getElementById("networkTabs");
    const tableHead = document.getElementById("tableHead");
    const tableBody = document.getElementById("tableBody");
    const tableMeta = document.getElementById("tableMeta");
    const pages = document.getElementById("pages");
    const pageInfo = document.getElementById("pageInfo");
    const slides = document.getElementById("slides");

    function renderTabs(container, list, current, handler) {
      container.innerHTML = "";
      list.forEach(item => {
        const b = document.createElement("button");
        b.className = "tab" + (item === current ? " active" : "");
        b.textContent = item;
        b.addEventListener("click", () => handler(item));
        container.appendChild(b);
      });
    }

    function sparkline(value, positive) {
      const pts = Array.from({ length: 16 }, (_, i) => {
        const y = 20 + Math.sin(i / 2 + value) * 8 + seeded(value + i, 6);
        return `${i * 8},${Math.max(4, Math.min(30, y)).toFixed(1)}`;
      }).join(" ");
      const color = positive ? "#16c784" : "#ea3943";
      return `<svg class="spark" viewBox="0 0 120 34" aria-hidden="true"><polyline fill="none" stroke="${color}" stroke-width="2" points="${pts}" /></svg>`;
    }

    function filteredData() {
      let rows = buildDataset(state.page);
      if (state.category !== "Top") rows = rows.filter(r => r.category === state.category);
      if (state.network !== "All Networks") rows = rows.filter(r => r.network === state.network);
      if (state.network === "More") rows = rows.filter(r => !["BSC", "Solana", "Base", "Ethereum", "All Networks"].includes(r.network));

      if (state.filters.positive24h) rows = rows.filter(r => r.h24 > 0);
      if (state.filters.largeCapOnly) rows = rows.filter(r => r.marketCap >= 1e10);
      if (state.filters.highVolume) rows = rows.filter(r => r.volume >= 1e9);

      rows.sort((a, b) => {
        const k = state.sortKey;
        const left = a[k], right = b[k];
        const dir = state.sortDir === "asc" ? 1 : -1;
        if (typeof left === "number") return (left - right) * dir;
        return String(left).localeCompare(String(right)) * dir;
      });

      return rows;
    }

    function renderHeader() {
      tableHead.innerHTML = "";
      columnsDef.forEach(c => {
        if (!state.columns[c.key]) return;
        const th = document.createElement("th");
        const marker = state.sortKey === c.key ? (state.sortDir === "asc" ? " ↑" : " ↓") : "";
        th.textContent = c.label + marker;
        if (c.sortable) {
          th.addEventListener("click", () => {
            if (state.sortKey === c.key) state.sortDir = state.sortDir === "asc" ? "desc" : "asc";
            else { state.sortKey = c.key; state.sortDir = "asc"; }
            render();
          });
        }
        tableHead.appendChild(th);
      });
    }

    function renderBody() {
      const rows = filteredData();
      tableBody.innerHTML = "";

      const indexRow = document.createElement("tr");
      const idxCells = [];
      if (state.columns.rank) idxCells.push(`<td style="font-family:var(--sans);font-weight:700">—</td>`);
