      { title: "New: On-chain Risk Monitor", text: "Identify abnormal token movement before market reacts.", cta: "Open Monitor" }
    ];

    const baseCoins = [
      ["Bitcoin", "BTC", 75612.78, "#f7931a"],
      ["Ethereum", "ETH", 2356.00, "#627eea"],
      ["Tether", "USDT", 1.00, "#26a17b"],
      ["BNB", "BNB", 610.42, "#f3ba2f"],
      ["Solana", "SOL", 168.35, "#14f195"],
      ["XRP", "XRP", 0.62, "#23292f"],
      ["USDC", "USDC", 1.00, "#2775ca"],
      ["Dogecoin", "DOGE", 0.19, "#c2a633"],
      ["Cardano", "ADA", 0.71, "#0033ad"],
      ["TRON", "TRX", 0.13, "#ef0027"]
    ];

    function formatMoney(value) {
      if (value >= 1e12) return `$${(value / 1e12).toFixed(2)}T`;
      if (value >= 1e9) return `$${(value / 1e9).toFixed(2)}B`;
      if (value >= 1e6) return `$${(value / 1e6).toFixed(2)}M`;
      return `$${value.toLocaleString(undefined, { maximumFractionDigits: 2 })}`;
    }

    function formatPrice(value) {
      const digits = value >= 1000 ? 2 : value >= 1 ? 2 : 4;
      return `$${value.toLocaleString(undefined, { minimumFractionDigits: digits, maximumFractionDigits: digits })}`;
    }

    function pct(v) {
      const sign = v > 0 ? "+" : "";
      return `${sign}${v.toFixed(2)}%`;
    }

    function seeded(i, scale = 1) {
      const x = Math.sin(i * 999) * 10000;
      return ((x - Math.floor(x)) - 0.5) * scale;
    }

    function buildDataset(page = 1) {
      const list = [];
      for (let i = 0; i < 100; i++) {
        const rank = (page - 1) * 100 + i + 1;
        const tpl = baseCoins[i % baseCoins.length];
        const drift = 1 + seeded(rank, 0.5) / 3;
        const price = tpl[2] * Math.max(0.25, drift);
        const marketCap = Math.abs(price * (3e7 + rank * 140000));
        const volume = marketCap * (0.03 + Math.abs(seeded(rank + 20, 0.2)));
        const supply = Math.max(100000, marketCap / Math.max(price, 0.01));
        const h1 = seeded(rank + 2, 2.8);
        const h24 = seeded(rank + 9, 8.2);
        const d7 = seeded(rank + 33, 20);

        let category = categories[0];
        if (rank % 5 === 0) category = "Trending";
        if (rank % 7 === 0) category = "Watchlist";
        if (rank % 11 === 0) category = "Prediction Markets";
        if (rank % 13 === 0) category = "Most Visited";
        if (rank % 17 === 0) category = "New";

        const network = rank % 6 === 0 ? "BSC" : rank % 5 === 0 ? "Solana" : rank % 4 === 0 ? "Base" : rank % 3 === 0 ? "Ethereum" : "All Networks";

        list.push({
          rank,
          name: `${tpl[0]} ${rank > 10 ? rank : ""}`.trim(),
          symbol: tpl[1],
          color: tpl[3],
          price,
          h1,
          h24,
          d7,
          marketCap,
          volume,
          supply,
          category,
          network
        });
      }

      list[0].price = 75612.78;
      list[1].price = 2356.00;
      list[0].marketCap = 1.51e12;
      list[1].volume = 2.8435e11;
      list[0].supply = 20010000;
      list[9].price = 88.25;
      return list;
    }

    let state = {
      category: "Top",
      network: "All Networks",
      page: 1,
      sortKey: "rank",
      sortDir: "asc",
      slide: 0,
      columns: Object.fromEntries(columnsDef.map(c => [c.key, true])),
      filters: { positive24h: false, largeCapOnly: false, highVolume: false }
    };

    const categoryTabs = document.getElementById("categoryTabs");
    const networkTabs = document.getElementById("networkTabs");
    const tableHead = document.getElementById("tableHead");
    const tableBody = document.getElementById("tableBody");
    const tableMeta = document.getElementById("tableMeta");
    const pages = document.getElementById("pages");
    const pageInfo = document.getElementById("pageInfo");
    const slides = document.getElementById("slides");

    function renderTabs(container, list, current, handler) {
      container.innerHTML = "";
      list.forEach(item => {
        const b = document.createElement("button");
        b.className = "tab" + (item === current ? " active" : "");
        b.textContent = item;
        b.addEventListener("click", () => handler(item));
        container.appendChild(b);
      });
    }

    function sparkline(value, positive) {
      const pts = Array.from({ length: 16 }, (_, i) => {
        const y = 20 + Math.sin(i / 2 + value) * 8 + seeded(value + i, 6);
        return `${i * 8},${Math.max(4, Math.min(30, y)).toFixed(1)}`;
      }).join(" ");
      const color = positive ? "#16c784" : "#ea3943";
      return `<svg class="spark" viewBox="0 0 120 34" aria-hidden="true"><polyline fill="none" stroke="${color}" stroke-width="2" points="${pts}" /></svg>`;
    }

    function filteredData() {
      let rows = buildDataset(state.page);
      if (state.category !== "Top") rows = rows.filter(r => r.category === state.category);
      if (state.network !== "All Networks") rows = rows.filter(r => r.network === state.network);
      if (state.network === "More") rows = rows.filter(r => !["BSC", "Solana", "Base", "Ethereum", "All Networks"].includes(r.network));

      if (state.filters.positive24h) rows = rows.filter(r => r.h24 > 0);
      if (state.filters.largeCapOnly) rows = rows.filter(r => r.marketCap >= 1e10);
      if (state.filters.highVolume) rows = rows.filter(r => r.volume >= 1e9);

      rows.sort((a, b) => {
        const k = state.sortKey;
        const left = a[k], right = b[k];
        const dir = state.sortDir === "asc" ? 1 : -1;
        if (typeof left === "number") return (left - right) * dir;
        return String(left).localeCompare(String(right)) * dir;
      });

      return rows;
    }

    function renderHeader() {
      tableHead.innerHTML = "";
      columnsDef.forEach(c => {
        if (!state.columns[c.key]) return;
        const th = document.createElement("th");
        const marker = state.sortKey === c.key ? (state.sortDir === "asc" ? " ↑" : " ↓") : "";
        th.textContent = c.label + marker;
        if (c.sortable) {
          th.addEventListener("click", () => {
            if (state.sortKey === c.key) state.sortDir = state.sortDir === "asc" ? "desc" : "asc";
            else { state.sortKey = c.key; state.sortDir = "asc"; }
            render();
          });
        }
        tableHead.appendChild(th);
      });
    }

    function renderBody() {
      const rows = filteredData();
      tableBody.innerHTML = "";

      const indexRow = document.createElement("tr");
      const idxCells = [];
      if (state.columns.rank) idxCells.push(`<td style="font-family:var(--sans);font-weight:700">—</td>`);
      if (state.columns.name) idxCells.push(`<td><div class="coin"><span class="dot" style="background:#2b64ff">20</span><span>CoinTracker 20 Index</span></div></td>`);
      if (state.columns.price) idxCells.push(`<td>$154.29</td>`);
      if (state.columns.h1) idxCells.push(`<td class="pos">+0.21%</td>`);
      if (state.columns.h24) idxCells.push(`<td class="pos">+1.15%</td>`);
      if (state.columns.d7) idxCells.push(`<td class="pos">+4.97%</td>`);
      if (state.columns.marketCap) idxCells.push(`<td>$3.02T</td>`);
      if (state.columns.volume) idxCells.push(`<td>$188.40B</td>`);
      if (state.columns.supply) idxCells.push(`<td>N/A</td>`);
      if (state.columns.spark) idxCells.push(`<td>${sparkline(88, true)}</td>`);
      indexRow.innerHTML = idxCells.join("");
      tableBody.appendChild(indexRow);

      rows.forEach(r => {
        const tr = document.createElement("tr");
        const cells = [];
        if (state.columns.rank) cells.push(`<td style="font-family:var(--sans);font-weight:600;color:var(--text)">${r.rank}</td>`);
        if (state.columns.name) cells.push(`<td><div class="coin"><span class="dot" style="background:${r.color}">${r.symbol[0]}</span><span>${r.name} <span class="sym">${r.symbol}</span></span></div></td>`);
        if (state.columns.price) cells.push(`<td>${formatPrice(r.price)}</td>`);
        if (state.columns.h1) cells.push(`<td class="${r.h1 >= 0 ? "pos" : "neg"}">${pct(r.h1)}</td>`);
        if (state.columns.h24) cells.push(`<td class="${r.h24 >= 0 ? "pos" : "neg"}">${pct(r.h24)}</td>`);
        if (state.columns.d7) cells.push(`<td class="${r.d7 >= 0 ? "pos" : "neg"}">${pct(r.d7)}</td>`);
        if (state.columns.marketCap) cells.push(`<td>${formatMoney(r.marketCap)}</td>`);
        if (state.columns.volume) cells.push(`<td>${formatMoney(r.volume)}</td>`);
        if (state.columns.supply) cells.push(`<td>${(r.supply / 1e6).toFixed(2)}M ${r.symbol}</td>`);
        if (state.columns.spark) cells.push(`<td>${sparkline(r.rank, r.d7 >= 0)}</td>`);
        tr.innerHTML = cells.join("");
        tableBody.appendChild(tr);
      });

      tableMeta.textContent = `${rows.length} assets · ${state.category} · ${state.network}`;
    }

    function renderPagination() {
      pages.innerHTML = "";
      const visible = [1, 2, 3, 4, 84];
      visible.forEach((p, i) => {
        const b = document.createElement("button");
        b.className = "page-btn" + (state.page === p ? " active" : "");
        b.textContent = p;
        b.addEventListener("click", () => { state.page = p; render(); });
        pages.appendChild(b);
        if (i === 3) {
          const ell = document.createElement("span");
          ell.textContent = "...";
          ell.style.padding = "0 4px";
          ell.style.color = "var(--muted)";
          pages.appendChild(ell);
        }
      });
      pageInfo.textContent = `Page ${state.page} of 84`;
    }

    function renderDrawers() {
      const columnsPanel = document.getElementById("columnsPanel");
      const filtersPanel = document.getElementById("filtersPanel");

      columnsPanel.innerHTML = columnsDef.map(c => `
        <label style="display:flex;gap:8px;align-items:center;cursor:pointer">
          <input type="checkbox" data-col="${c.key}" ${state.columns[c.key] ? "checked" : ""}>
          <span>${c.label}</span>
        </label>
      `).join("");

      filtersPanel.innerHTML = `
        <label style="display:flex;gap:8px;align-items:center;cursor:pointer"><input type="checkbox" data-filter="positive24h" ${state.filters.positive24h ? "checked" : ""}> 24h gainers only</label>
        <label style="display:flex;gap:8px;align-items:center;cursor:pointer"><input type="checkbox" data-filter="largeCapOnly" ${state.filters.largeCapOnly ? "checked" : ""}> Market cap &gt; $10B</label>
        <label style="display:flex;gap:8px;align-items:center;cursor:pointer"><input type="checkbox" data-filter="highVolume" ${state.filters.highVolume ? "checked" : ""}> Volume &gt; $1B</label>
      `;

      columnsPanel.querySelectorAll("input[data-col]").forEach(input => {
        input.addEventListener("change", e => {
          const key = e.target.getAttribute("data-col");
          state.columns[key] = e.target.checked;
          render();
        });
      });

      filtersPanel.querySelectorAll("input[data-filter]").forEach(input => {
        input.addEventListener("change", e => {
          const key = e.target.getAttribute("data-filter");
          state.filters[key] = e.target.checked;
          render();
        });
      });
    }

    function renderSlides() {
      slides.innerHTML = promotionalSlides.map(s => `
        <article class="slide">
          <div>
            <h3>${s.title}</h3>
            <p>${s.text}</p>
          </div>
          <button>${s.cta}</button>
        </article>
      `).join("");
      slides.style.transform = `translateX(-${state.slide * 100}%)`;
    }

    function render() {
      renderTabs(categoryTabs, categories, state.category, (item) => { state.category = item; render(); });
      renderTabs(networkTabs, networks, state.network, (item) => { state.network = item; render(); });
      renderHeader();
      renderBody();
      renderPagination();
      renderDrawers();
      renderSlides();
    }

    document.getElementById("columnsBtn").addEventListener("click", (e) => {
      const panel = document.getElementById("columnsPanel");
      panel.classList.toggle("active");
      e.currentTarget.setAttribute("aria-expanded", panel.classList.contains("active"));
    });

    document.getElementById("filtersBtn").addEventListener("click", (e) => {
      const panel = document.getElementById("filtersPanel");
      panel.classList.toggle("active");
      e.currentTarget.setAttribute("aria-expanded", panel.classList.contains("active"));
    });

    document.getElementById("prevSlide").addEventListener("click", () => {
      state.slide = (state.slide - 1 + promotionalSlides.length) % promotionalSlides.length;
      renderSlides();
    });

    document.getElementById("nextSlide").addEventListener("click", () => {
      state.slide = (state.slide + 1) % promotionalSlides.length;
      renderSlides();
    });

    setInterval(() => {
      state.slide = (state.slide + 1) % promotionalSlides.length;
      renderSlides();
    }, 5000);

    document.getElementById("readMore").addEventListener("click", (e) => {
      const more = document.getElementById("moreSummary");
      more.classList.toggle("hidden");
      e.currentTarget.textContent = more.classList.contains("hidden") ? "Read More" : "Show Less";
    });

    render();
  </script>
</body>
</html>
